const response = $input.first().json || {};
const data = response.data || {};
const chain = Array.isArray(data.optionsChain) ? data.optionsChain : [];
const contracts = chain.filter(option => ['CE', 'PE'].includes(option.option_type) && Number(option.oi) > 0);
if (response.s !== 'ok' || contracts.length === 0) return [];

const calls = contracts.filter(option => option.option_type === 'CE');
const puts = contracts.filter(option => option.option_type === 'PE');
const maxOiStrike = options => options.reduce((best, option) => Number(option.oi) > Number(best.oi) ? option : best, options[0]);
const callMax = calls.length ? maxOiStrike(calls) : null;
const putMax = puts.length ? maxOiStrike(puts) : null;
const callOi = Number(data.callOi || 0);
const putOi = Number(data.putOi || 0);
const pcr = callOi > 0 ? (putOi / callOi).toFixed(2) : 'n/a';
const expiries = Array.isArray(data.expiryData) ? data.expiryData.filter(item => Number(item.expiry) * 1000 >= Date.now()).sort((a, b) => Number(a.expiry) - Number(b.expiry)) : [];
const expiry = expiries[0] ? expiries[0].date : 'not provided';
const spot = chain.find(option => option.option_type === '' && Number(option.strike_price) === -1 && option.ltp != null);
const signal = $('When Executed by Another Workflow').first().json;
const capturedAt = new Intl.DateTimeFormat('en-IN', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' }).format(new Date());
const tilt = putOi > callOi ? 'Put OI is higher than Call OI' : putOi < callOi ? 'Call OI is higher than Put OI' : 'Call and Put OI are balanced';

const lines = [
  `📊 Options snapshot: ${signal.stock_name_raw || signal.nse_symbol}`,
  `Ticker: ${signal.nse_symbol} | Expiry: ${expiry}`,
  `Underlying LTP: ${spot ? '₹' + spot.ltp : 'not returned'} | Signal trigger: ₹${signal.entry_price}`,
  `Aggregate OI: Calls ${callOi.toLocaleString('en-IN')} | Puts ${putOi.toLocaleString('en-IN')} | Put/Call ratio ${pcr}`,
  `Highest Call OI in returned strikes: ${callMax ? '₹' + callMax.strike_price : 'n/a'} | Highest Put OI: ${putMax ? '₹' + putMax.strike_price : 'n/a'}`,
  `${tilt}; this is positioning context, not a buy/sell recommendation.`,
  `Fetched: ${capturedAt} IST`
];
return [{ json: { options_text: lines.join('\n') } }];
